      for (let i = 0; i < numFrames; i++) {
        this.ringBufferL[this.writeIndex] = floatData[i * 2];
        this.ringBufferR[this.writeIndex] = floatData[i * 2 + 1];
        this.writeIndex = (this.writeIndex + 1) % this.bufferSize;
      }
